+
+// GetGenerationRetentionDays returns the retention window for archived
+// checkpoints v2 generations. Invalid, missing, or non-positive values fall
+// back to the documented default.
+func (s *EntireSettings) GetGenerationRetentionDays() int {
+	if s.StrategyOptions == nil {
+		return defaultGenerationRetentionDays
+	}
+
+	val, ok := s.StrategyOptions["generation_retention_days"]
+	if !ok {
+		return defaultGenerationRetentionDays
+	}
+
+	switch days := val.(type) {
+	case int:
+		if days > 0 {
+			return days
+		}
+	case float64:
+		intDays := int(days)
+		if intDays > 0 && days == float64(intDays) {
+			return intDays
+		}
+	}
+
+	return defaultGenerationRetentionDays
+}

